// Load fake-native.hdf5, exported by `aida-data export fake-native`.
// Generated by aida-data 0.0.0 for HighFive 3.x (H5Easy), tested with HighFive 3.3.0.
// Generated without the file, so it checks the objects that not every dataset has
// with `file.exist`. Get the file with `aida-data export fake-native`, then run
// `aida-data snippet fake-native` again for a version made for it.
//
// Build: h5c++ -std=c++17 -I/path/to/highfive/include load.cpp -o load
// or with CMake:
//   find_package(HighFive REQUIRED)
//   target_link_libraries(load HighFive::HighFive)
// HighFive comes from a package manager (apt install libhighfive-dev,
// conda install highfive, vcpkg install highfive) or a git submodule.
// With HighFive 2.x the CMake target is `HighFive` and DataSet::read_raw(T*)
// is DataSet::read(T*).
#include <highfive/H5Easy.hpp>

#include <cstdint>
#include <iostream>
#include <string>
#include <vector>

int main() {
    H5Easy::File file("fake-native.hdf5", H5Easy::File::ReadOnly);

    // One row per point.
    auto train = H5Easy::load<std::vector<std::vector<float>>>(file, "/train");

    // One row per query.
    auto test = H5Easy::load<std::vector<std::vector<float>>>(file, "/test");

    // Ids of the nearest neighbors of each query, in train.
    auto neighbors = H5Easy::load<std::vector<std::vector<int64_t>>>(file, "/neighbors");

    // Distances from each query to those neighbors.
    auto distances = H5Easy::load<std::vector<std::vector<float>>>(file, "/distances");

    // Distance of the dataset, e.g. "euclidean" or "angular".
    auto distance = H5Easy::loadAttribute<std::string>(file, "/", "distance");

    // For large data, read into one contiguous row-major buffer instead:
    //   HighFive::DataSet ds = file.getDataSet("/train");
    //   auto dims = ds.getDimensions();
    //   std::vector<float> flat(dims[0] * dims[1]);
    //   ds.read_raw(flat.data());
    // or, with H5_USE_EIGEN defined before including HighFive:
    //   using Matrix = Eigen::Matrix<float, Eigen::Dynamic, Eigen::Dynamic,
    //                                Eigen::RowMajor>;
    //   auto m = H5Easy::load<Matrix>(file, "/train");

    // The shapes of what was loaded.
    std::cout << "train: " << train.size() << " x " << (train.empty() ? 0 : train[0].size()) << "\n";
    std::cout << "test: " << test.size() << " x " << (test.empty() ? 0 : test[0].size()) << "\n";
    std::cout << "neighbors: " << neighbors.size() << " x " << (neighbors.empty() ? 0 : neighbors[0].size()) << "\n";
    std::cout << "distances: " << distances.size() << " x " << (distances.empty() ? 0 : distances[0].size()) << "\n";
    std::cout << "distance: " << distance << "\n";
}
